module.exports = function (RED) {
    function StartNode(config) {
        RED.nodes.createNode(this, config);
        var node = this;

        node.space = config.space;

        // 把编辑器里存的 deviceTypes 传过来
        node.deviceTypes = config.deviceTypes || [];

        node.on('input', function (msg) {
            msg.space = node.space;

            // 写入全局变量
            var globalContext = node.context().global;
            if (node.deviceTypes && Array.isArray(node.deviceTypes)) {
                globalContext.set("deviceTypesBySpace", node.deviceTypes);
            }

            node.send(msg);
        });
    }

    RED.nodes.registerType("start", StartNode);
};